package com.piet.vms.ui;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.DefaultTableCellRenderer;
import javax.swing.table.JTableHeader;
import java.awt.*;

public final class Theme {
    public static final Color NAVY=new Color(19,37,64), NAVY2=new Color(29,54,86), BLUE=new Color(43,105,183), BG=new Color(244,247,252), TEXT=new Color(33,47,67), MUTED=new Color(105,120,140), BORDER=new Color(224,231,241), WHITE=Color.WHITE, GREEN=new Color(34,153,95), RED=new Color(211,63,78), ORANGE=new Color(222,129,34);
    private Theme(){}
    public static void install(){try{UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());}catch(Exception ignored){};Font f=new Font("Segoe UI",Font.PLAIN,13);UIManager.put("Label.font",f);UIManager.put("Button.font",new Font("Segoe UI",Font.BOLD,13));UIManager.put("TextField.font",f);UIManager.put("PasswordField.font",f);UIManager.put("TextArea.font",f);UIManager.put("ComboBox.font",f);UIManager.put("Table.font",f);UIManager.put("OptionPane.messageFont",f);UIManager.put("OptionPane.buttonFont",f);UIManager.put("Panel.background",BG);}
    public static JButton button(String text,Color color){JButton b=new JButton(text);b.setBackground(color);b.setForeground(WHITE);b.setFocusPainted(false);b.setBorderPainted(false);b.setOpaque(true);b.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));b.setBorder(new EmptyBorder(10,16,10,16));return b;}
    public static JLabel title(String text){JLabel l=new JLabel(text);l.setFont(new Font("Segoe UI",Font.BOLD,24));l.setForeground(TEXT);return l;}
    public static JPanel card(){JPanel p=new JPanel(new BorderLayout(0,8));p.setBackground(WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(BORDER),new EmptyBorder(18,18,18,18)));return p;}
    public static JScrollPane scroll(JTable t){JScrollPane s=new JScrollPane(t);s.setBorder(BorderFactory.createLineBorder(BORDER));s.getViewport().setBackground(WHITE);s.getVerticalScrollBar().setUnitIncrement(16);return s;}
    public static JTable table(String... columns){JTable t=new JTable(new javax.swing.table.DefaultTableModel(columns,0){@Override public boolean isCellEditable(int r,int c){return false;}});t.setRowHeight(38);t.setFillsViewportHeight(true);t.setShowVerticalLines(false);t.setGridColor(new Color(235,239,246));t.setSelectionBackground(new Color(222,235,252));t.setSelectionForeground(TEXT);t.setForeground(TEXT);t.setBackground(WHITE);t.setAutoCreateRowSorter(false);t.setDefaultRenderer(Object.class,new DefaultTableCellRenderer(){@Override public Component getTableCellRendererComponent(JTable table,Object value,boolean selected,boolean focus,int row,int col){super.getTableCellRendererComponent(table,value,selected,focus,row,col);setBorder(new EmptyBorder(0,10,0,8));if(!selected)setBackground(row%2==0?WHITE:new Color(248,250,253));return this;}});JTableHeader h=t.getTableHeader();h.setPreferredSize(new Dimension(h.getPreferredSize().width,42));h.setReorderingAllowed(false);h.setDefaultRenderer(new DefaultTableCellRenderer(){@Override public Component getTableCellRendererComponent(JTable table,Object value,boolean selected,boolean focus,int row,int col){JLabel l=(JLabel)super.getTableCellRendererComponent(table,value,selected,focus,row,col);l.setOpaque(true);l.setBackground(NAVY2);l.setForeground(WHITE);l.setFont(new Font("Segoe UI",Font.BOLD,12));l.setBorder(new EmptyBorder(0,10,0,8));return l;}});return t;}
    public static JPanel stat(String value,String label,Color accent){JPanel p=new JPanel(new GridLayout(2,1,0,6));p.setBackground(WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(4,0,0,0,accent),BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(BORDER),new EmptyBorder(14,16,14,16))));JLabel v=new JLabel(value);v.setFont(new Font("Segoe UI",Font.BOLD,30));v.setForeground(accent);JLabel l=new JLabel(label);l.setForeground(MUTED);p.add(v);p.add(l);return p;}
    public static void styleInput(JComponent c){c.setFont(new Font("Segoe UI",Font.PLAIN,13));c.setBackground(WHITE);c.setForeground(TEXT);c.setPreferredSize(new Dimension(Math.max(180,c.getPreferredSize().width),36));}
}
